import { describe, expect, it, vi } from "vitest";
import { loadGoldenFixtures } from "../tests/brokerEventContract";
import {
  ConversationEventType,
  type ConversationEvent,
  type RawEvent,
  type Utterance,
  UtteranceType,
} from "../types";
import {
  isProtoJsonEvent,
  normalizeTrackerEvent,
  normalizeTrackerEvents,
  normalizeTrackerPayload,
  toReplayEvent,
} from "./broker-event";
import { mapRawEventsToConversationEvents } from "./conversation";

const goldenFixtures = loadGoldenFixtures();

// Anonymized fixtures reuse the base payload key. The filename only exists so
// the contract suite can tell them apart from the plain user/bot/memory events.
const ANONYMIZED_FIXTURE_EVENTS: Record<string, RawEvent["event"]> = {
  user_anonymized: "user",
  bot_anonymized: "bot",
  memory_set_anonymized: "memory_set",
};

const ANONYMIZED_AT = 1788855600.123;

function expectedEventName(fixtureName: string): string {
  return ANONYMIZED_FIXTURE_EVENTS[fixtureName] ?? fixtureName;
}

function goldenEnvelope(name: string): Record<string, unknown> {
  const fixture = goldenFixtures.find((candidate) => candidate.name === name);
  if (!fixture) {
    throw new Error(`missing golden fixture ${name}`);
  }
  return fixture.envelope;
}

function normalize(envelope: Record<string, unknown>): RawEvent {
  const rawEvent = normalizeTrackerEvent(envelope);
  if (!rawEvent) {
    throw new Error("expected a valid ProtoJSON envelope");
  }
  return rawEvent;
}

const flatUserEvent = {
  event: "user",
  timestamp: 1.0,
  text: "hi",
  metadata: {},
} as unknown as RawEvent;

describe("isProtoJsonEvent", () => {
  it("is false for classic flat events carrying an `event` key", () => {
    expect(isProtoJsonEvent(flatUserEvent)).toBe(false);
  });

  it("is true for any other object", () => {
    expect(isProtoJsonEvent(goldenEnvelope("user"))).toBe(true);
    expect(isProtoJsonEvent({})).toBe(true);
  });

  it("is false for non-objects", () => {
    expect(isProtoJsonEvent(null)).toBe(false);
    expect(isProtoJsonEvent("user")).toBe(false);
    expect(isProtoJsonEvent([goldenEnvelope("user")])).toBe(false);
  });
});

describe("brokerEventToRawEvent", () => {
  it.each(goldenFixtures)("names golden fixture $name by its payload key", ({ name, envelope }) => {
    const rawEvent = normalize(envelope);
    expect(rawEvent.event).toBe(expectedEventName(name));
    expect(rawEvent.timestamp).toBe(envelope.timestamp);
    expect(rawEvent.conversation_id).toBe(envelope.conversation_id);
    expect(rawEvent.event_id).toBe(envelope.event_id);
    expect(rawEvent.sequence).toBe(envelope.sequence);
    expect(rawEvent.metadata).toEqual({ session_id: envelope.session_id });
  });

  it.each(Object.entries(ANONYMIZED_FIXTURE_EVENTS))(
    "keeps anonymized_at on golden fixture %s",
    (name) => {
      const rawEvent = normalize(goldenEnvelope(name)) as RawEvent & {
        anonymized_at?: number;
      };
      expect(rawEvent.anonymized_at).toBeCloseTo(ANONYMIZED_AT);
    },
  );

  it("keeps the original envelope for replay", () => {
    const envelope = goldenEnvelope("user");
    expect(normalize(envelope).protoJsonSource).toEqual(envelope);
  });

  it("preserves the original wire envelope for replay, including unknown keys", () => {
    const wire = { ...goldenEnvelope("user"), future_field: "keep-me" };
    const rawEvent = normalizeTrackerEvent(wire);
    expect(rawEvent?.protoJsonSource).toEqual(wire);
    expect(toReplayEvent(rawEvent!)).toEqual(wire);
  });

  it("decodes the envelope metadata JSON document and lifts session_id into it", () => {
    const rawEvent = normalize({
      ...goldenEnvelope("bot"),
      metadata: JSON.stringify({ utter_action: "utter_greet", latency_breakdown: { x: 1 } }),
      session_id: "session-9",
    });
    expect(rawEvent.metadata).toEqual({
      utter_action: "utter_greet",
      latency_breakdown: { x: 1 },
      session_id: "session-9",
    });
  });

  it("falls back to empty metadata when the document is malformed", () => {
    const rawEvent = normalize({
      ...goldenEnvelope("bot"),
      metadata: "{not json",
      session_id: null,
    });
    expect(rawEvent.metadata).toEqual({});
  });

  it("decodes memory_set.value_json once so integers stay integers", () => {
    const rawEvent = normalize(goldenEnvelope("memory_set"));
    expect(rawEvent.key).toBe("amount");
    expect(rawEvent.value).toBe(42);
    expect(rawEvent).not.toHaveProperty("value_json");
  });

  it("keeps a malformed value_json as its raw string", () => {
    const rawEvent = normalize({
      ...goldenEnvelope("memory_set"),
      memory_set: { key: "amount", value_json: "{broken" },
    });
    expect(rawEvent.value).toBe("{broken");
  });

  it("decodes tool_executed arguments_json / result_json and renames them", () => {
    const rawEvent = normalize({
      ...goldenEnvelope("tool_executed"),
      tool_executed: {
        tool_name: "lookup_account",
        arguments_json: '{"account_id": 42}',
        source: "mcp",
        result_json: '{"balance": 10.5}',
        is_error: false,
        error_message: null,
        mcp_server: "bank",
      },
    });
    expect(rawEvent.tool_name).toBe("lookup_account");
    expect(rawEvent.arguments).toEqual({ account_id: 42 });
    expect(rawEvent.result).toEqual({ balance: 10.5 });
    expect(rawEvent.source).toBe("mcp");
    expect(rawEvent.mcp_server).toBe("bank");
    expect(rawEvent).not.toHaveProperty("arguments_json");
    expect(rawEvent).not.toHaveProperty("result_json");
  });

  it("maps a null tool result to null", () => {
    expect(normalize(goldenEnvelope("tool_executed")).result).toBeNull();
  });

  it("passes user parse_data and bot data through as objects", () => {
    const userEvent = normalize(goldenEnvelope("user"));
    expect(userEvent.text).toBe("I want to transfer money");
    expect(userEvent.parse_data).toMatchObject({ text: "I want to transfer money" });

    const botEvent = normalize({
      ...goldenEnvelope("bot"),
      bot: { text: "Pick one", data: { buttons: [{ title: "A", payload: "/a" }] } },
    });
    expect(botEvent.text).toBe("Pick one");
    expect(botEvent.data).toEqual({ buttons: [{ title: "A", payload: "/a" }] });
  });

  it("keeps the stack update as the JSON patch string the mapper expects", () => {
    expect(normalize(goldenEnvelope("stack")).update).toBe("[]");
  });
});

describe("normalizeTrackerEvent(s)", () => {
  it("passes classic flat events through untouched", () => {
    expect(normalizeTrackerEvent(flatUserEvent)).toBe(flatUserEvent);
  });

  it("drops an invalid ProtoJSON event and reports it", () => {
    const onInvalid = vi.fn();
    expect(normalizeTrackerEvent({ conversation_id: "c" }, onInvalid)).toBeUndefined();
    expect(onInvalid).toHaveBeenCalledTimes(1);
    expect(onInvalid.mock.calls[0][1]).toEqual({ conversation_id: "c" });
  });

  it("dual-reads a mixed list in order and skips only the invalid entries", () => {
    const onInvalid = vi.fn();
    const events = normalizeTrackerEvents(
      [flatUserEvent, { conversation_id: "c" }, goldenEnvelope("memory_set")],
      onInvalid,
    );
    expect(events.map((event) => event.event)).toEqual(["user", "memory_set"]);
    expect(onInvalid).toHaveBeenCalledTimes(1);
  });
});

describe("normalizeTrackerPayload", () => {
  it("proxies onInvalid to normalizeTrackerEvents", () => {
    const onInvalid = vi.fn();
    const payload = normalizeTrackerPayload(
      { sender_id: "s", events: [flatUserEvent, { conversation_id: "c" }] },
      onInvalid,
    ) as { events: { event: string }[] };

    expect(payload.events.map((event) => event.event)).toEqual(["user"]);
    expect(onInvalid).toHaveBeenCalledTimes(1);
  });
});

describe("toReplayEvent", () => {
  it("returns the original ProtoJSON envelope for normalized events", () => {
    const envelope = goldenEnvelope("user");
    expect(toReplayEvent(normalize(envelope))).toEqual(envelope);
  });

  it("returns classic flat events as-is", () => {
    expect(toReplayEvent(flatUserEvent)).toBe(flatUserEvent);
  });
});

describe("ProtoJSON events through mapRawEventsToConversationEvents", () => {
  const mapped = mapRawEventsToConversationEvents(
    normalizeTrackerEvents([
      goldenEnvelope("user"),
      goldenEnvelope("bot"),
      goldenEnvelope("memory_set"),
      goldenEnvelope("skill_activated"),
      goldenEnvelope("tool_executed"),
      goldenEnvelope("ordered_block_entered"),
      goldenEnvelope("action"),
    ]),
  );

  it("renders user and bot payloads as utterances", () => {
    const [user, bot] = mapped as Utterance[];
    expect(user.type).toBe(UtteranceType.User);
    expect(user.text).toBe("I want to transfer money");
    expect(bot.type).toBe(UtteranceType.Bot);
    expect(bot.text).toBe("How can I help?");
  });

  it("renders memory_set with the decoded value", () => {
    const memorySet = mapped[2] as ConversationEvent;
    expect(memorySet.conversationEventType).toBe(ConversationEventType.MemorySet);
    expect(memorySet.name).toBe("amount");
    expect(memorySet.value).toBe(42);
  });

  it("renders skill and ordered-block lifecycle events", () => {
    const skill = mapped[3] as ConversationEvent;
    expect(skill.conversationEventType).toBe(ConversationEventType.SkillActivated);
    expect(skill.skillId).toBe("transfer_money");

    const block = mapped[5] as ConversationEvent;
    expect(block.conversationEventType).toBe(ConversationEventType.OrderedBlockEntered);
    expect(block.skillId).toBe("transfer_money");
    expect(block.blockId).toBe("confirm");
  });

  it("renders tool_executed with decoded arguments", () => {
    const tool = mapped[4] as ConversationEvent;
    expect(tool.conversationEventType).toBe(ConversationEventType.ToolExecuted);
    expect(tool.name).toBe("lookup_account");
    expect(tool.metadata.tool_arguments).toEqual({ account_id: 42 });
    expect(tool.metadata.tool_source).toBe("local");
  });

  it("renders action with its name", () => {
    const action = mapped[6] as ConversationEvent;
    expect(action.conversationEventType).toBe(ConversationEventType.Action);
    expect(action.name).toBe("action_listen");
  });

  it("exposes the original envelope as the replay payload", () => {
    const rawEvent = mapped[0].metadata.rawEvent;
    expect(rawEvent && toReplayEvent(rawEvent)).toEqual(goldenEnvelope("user"));
  });
});
